from kr_sci import H, nq, num


def UNITS(g):
    return {"integrated-science-1": I1, "integrated-science-2": I2}[g]()


B1, M1, S1 = "과학의 기초", "물질과 규칙성", "시스템과 상호작용"
C2, E2, F2 = "변화와 다양성", "환경과 에너지", "과학과 미래 사회"


def f_measure(R):
    k = R.choice(["unit", "bin", "err", "sig"])
    if k == "unit":
        a, u1, f, u2 = R.choice([(3.6, "km/h", 1 / 3.6, "m/s"), (72, "km/h", 1 / 3.6, "m/s"), (2.5, "kg", 1000, "g"), (450, "mL", 0.001, "L"), (0.25, "m", 100, "cm"),
                                  (1500, "g", 0.001, "kg"), (36, "km/h", 1 / 3.6, "m/s"), (5, "μm", 0.001, "mm"), (2, "min", 60, "s"), (3, "L", 1000, "cm³")])
        return nq("다음 양을 %s 단위로 나타내면 얼마일까요? %s %s" % (u2, num(a), u1), a * f, [a / f, a * f * 10, a * f / 10], u2, "%s %s = %s %s입니다." % (num(a), u1, num(a * f), u2))
    if k == "bin":
        n = R.choice([5, 6, 9, 10, 12, 13, 7, 11])
        return it_bin(n)
    if k == "err":
        t, m = R.choice([(10, 9.8), (50, 49), (100, 98), (20, 19.5), (9.8, 9.6), (200, 196)])
        e = abs(t - m) / t * 100
        return nq("참값이 %s인 양을 측정한 값이 %s일 때 상대 오차는 몇 %%일까요?" % (num(t), num(m)), e, [abs(t - m), e * 10, 100 - e], "%", "상대 오차 = |참값 − 측정값| ÷ 참값 × 100 = %s ÷ %s × 100 = %s %%입니다." % (num(abs(t - m)), num(t), num(e)))
    b = R.choice([2, 3, 4, 5, 8])
    return nq("%d비트로 나타낼 수 있는 서로 다른 정보의 가짓수는?" % b, 2 ** b, [2 * b, b * b, 2 ** b - 1, 10 ** b], "가지", "1비트는 0과 1의 2가지이므로 %d비트는 2^%d = %d가지입니다." % (b, b, 2 ** b))


def it_bin(n):
    from kr_sci import it
    b = bin(n)[2:]
    w = {bin(n + 1)[2:], bin(n - 1)[2:], b[::-1] if b[::-1] != b else bin(n + 2)[2:], bin(n * 2)[2:]}
    w.discard(b)
    return it("10진수 %d를 2진수로 나타낸 것은?" % n, b, sorted(w)[:3], "%d = %s이므로 2진수 %s입니다." % (n, " + ".join(str(2 ** i) for i in range(len(b) - 1, -1, -1) if b[len(b) - 1 - i] == "1"), b))


def f_mech(R):
    k = R.choice(["fallv", "fallh", "proj", "p", "imp", "force"])
    if k == "fallv":
        t = R.choice([1, 2, 3, 4, 5])
        return nq("물체를 가만히 떨어뜨렸습니다. %d초 후의 속력은 몇 m/s일까요? (중력 가속도 10 m/s², 공기 저항 무시)" % t, 10 * t, [5 * t * t, 10 * t * t, 10 / t], "m/s", "v = gt = 10 × %d = %d m/s입니다." % (t, 10 * t))
    if k == "fallh":
        t = R.choice([1, 2, 3, 4])
        return nq("물체를 가만히 떨어뜨렸습니다. %d초 동안 떨어진 거리는 몇 m일까요? (중력 가속도 10 m/s², 공기 저항 무시)" % t, 5 * t * t, [10 * t, 10 * t * t, 5 * t], "m", "s = ½gt² = ½ × 10 × %d² = %d m입니다." % (t, 5 * t * t))
    if k == "proj":
        v, t = R.choice([(10, 2), (5, 3), (20, 1), (15, 2), (8, 3)])
        return nq("높은 곳에서 물체를 수평 방향으로 %d m/s의 속력으로 던졌더니 %d초 뒤 땅에 떨어졌습니다. 수평 방향으로 이동한 거리는 몇 m일까요? (공기 저항 무시)" % (v, t), v * t, [v * t * t, 5 * t * t, v / t], "m",
                  "수평 방향은 등속 운동이므로 %d × %d = %d m입니다." % (v, t, v * t))
    if k == "p":
        m, v = R.choice([(2, 3), (0.5, 20), (60, 5), (1000, 20), (0.2, 30), (4, 2.5)])
        return nq("질량 %s kg인 물체가 %s m/s로 운동합니다. 운동량의 크기는 몇 kg·m/s일까요?" % (num(m), num(v)), m * v, [m / v, 0.5 * m * v * v, m + v], "kg·m/s", "p = mv = %s × %s = %s kg·m/s입니다." % (num(m), num(v), num(m * v)))
    if k == "imp":
        m, v1 = R.choice([(0.5, 20), (2, 10), (0.15, 40), (0.2, 30), (1, 15)])
        return nq("질량 %s kg인 공이 %s m/s로 날아오다 벽에 부딪혀 멈췄습니다. 공이 받은 충격량의 크기는 몇 N·s일까요?" % (num(m), num(v1)), m * v1, [m * v1 * 2, 0.5 * m * v1 * v1, v1 / m], "N·s",
                  "충격량 = 운동량의 변화량 = %s × %s − 0 = %s N·s입니다." % (num(m), num(v1), num(m * v1)))
    J, t = R.choice([(10, 0.1), (30, 0.5), (60, 0.2), (20, 0.01), (100, 2)])
    return nq("물체가 %s N·s의 충격량을 받는 데 %s초가 걸렸습니다. 물체가 받은 평균 힘의 크기는 몇 N일까요?" % (num(J), num(t)), J / t, [J * t, t / J, J], "N",
              "평균 힘 = 충격량 ÷ 충돌 시간 = %s ÷ %s = %s N입니다. 충돌 시간이 길수록 힘이 작아집니다." % (num(J), num(t), num(J / t)))


def f_energy2(R):
    k = R.choice(["eff", "loss", "turns", "pe"])
    if k == "eff":
        a, b = R.choice([(100, 25), (500, 150), (1000, 400), (200, 90), (800, 320), (50, 40)])
        return nq("열기관에 %d J의 에너지를 공급했더니 %d J의 일을 했습니다. 이 열기관의 효율은 몇 %%일까요?" % (a, b), 100 * b / a, [100 * (a - b) / a, b / a, a / b * 100], "%",
                  "효율 = 유용하게 쓰인 에너지 ÷ 공급한 에너지 × 100 = %d ÷ %d × 100 = %s %%입니다." % (b, a, num(100 * b / a)))
    if k == "loss":
        n = R.choice([2, 4, 10, 5])
        return nq("송전 전력과 송전선의 저항이 같을 때 송전 전압을 %d배로 높이면 송전선에서 손실되는 전력은 처음의 몇 배가 될까요?" % n, 1 / (n * n), [1 / n, n * n, n, 1 / (2 * n)], "배",
                  "전류가 1/%d로 줄고 손실 전력은 전류의 제곱에 비례하므로 1/%d배가 됩니다." % (n, n * n))
    if k == "turns":
        n1, n2, v1 = R.choice([(100, 200, 110), (500, 100, 220), (1000, 50, 220), (200, 1000, 20), (300, 600, 50)])
        return nq("1차 코일의 감은 수가 %d회, 2차 코일의 감은 수가 %d회인 변압기의 1차 코일에 %d V를 걸면 2차 코일의 전압은 몇 V일까요?" % (n1, n2, v1), v1 * n2 / n1, [v1 * n1 / n2, v1, v1 * n2], "V",
                  "전압은 감은 수에 비례하므로 %d × %d ÷ %d = %s V입니다." % (v1, n2, n1, num(v1 * n2 / n1)))
    m, h = R.choice([(1000, 50), (500, 100), (2000, 30), (1000, 80)])
    return nq("댐에서 물 %s kg이 %d m 아래로 떨어질 때 감소한 위치 에너지는 몇 J일까요? (중력 가속도 10 m/s²)" % (num(m), h), 10 * m * h, [m * h, 5 * m * h, 10 * m], "J", "Eₚ = mgh = %s × 10 × %d = %s J입니다." % (num(m), h, num(10 * m * h)))


